import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const sourcePath=path.join(root,'biographies','research-frontiers.json');
const outputPath=path.join(root,'biographies','research-frontiers-data.js');
const data=JSON.parse(await readFile(sourcePath,'utf8'));

const output=[
  '/* Generated by scripts/build-research-frontiers.mjs. Edit research-frontiers.json, not this file. */',
  `globalThis.RESEARCH_FRONTIERS=${JSON.stringify(data,null,2)};`,
  ''
].join('\n');

await writeFile(outputPath,output);
